#pragma once
static const char PORTAL_HTML[] =
"<!doctype html><html lang='zh-CN'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
"<title>Piko Passport 配网</title><style>body{font:16px system-ui;max-width:420px;margin:40px auto;padding:20px;background:#faf8f3;color:#283630}label{display:block;margin:16px 0}input,select,button{box-sizing:border-box;width:100%;padding:12px;font:inherit}button{background:#315e49;color:white;border:0;border-radius:8px;margin:8px 0}p{line-height:1.6}summary{cursor:pointer;margin-top:20px}small{color:#58645e}</style>"
"<h1>连接你的 Piko</h1><p>选择与电脑相同的 Wi-Fi，输入密码即可。设备会自动寻找局域网内的 Piko。</p>"
"<form id='f'><label>Wi-Fi 网络<select name='ssid' id='net' required disabled><option value=''>正在查找附近网络…</option></select></label>"
"<button type='button' id='scan'>重新扫描</button><p id='scanStatus' role='status'></p>"
"<label>Wi-Fi 密码<input name='password' type='password' maxlength='63' autocomplete='new-password' id='pw'></label>"
"<small>仅支持 2.4 GHz Wi-Fi。开放网络无需密码。</small>"
"<details id='advanced'><summary>手动配置（隐藏网络或自动发现失败时）</summary><label>隐藏 Wi-Fi 名称<input id='hiddenSsid' maxlength='32'></label>"
"<label>电脑局域网 IP（可选）<input name='host' placeholder='留空则自动发现'></label>"
"<label>配对码（手动指定电脑时填写）<input name='pairingCode' pattern='[0-9a-fA-F]{8}' maxlength='8'></label></details>"
"<button id='save' disabled>连接 Wi-Fi</button></form><p id='s' role='status'></p>"
"<script>const f=document.getElementById('f'),net=document.getElementById('net'),scan=document.getElementById('scan'),save=document.getElementById('save'),s=document.getElementById('s'),scanStatus=document.getElementById('scanStatus'),hiddenSsid=document.getElementById('hiddenSsid'),pw=document.getElementById('pw');"
"function selected(){const o=net.selectedOptions[0];pw.placeholder=o&&o.dataset.open==='true'?'此网络无需密码':'输入 Wi-Fi 密码';save.disabled=!net.value&&!hiddenSsid.value;net.required=!hiddenSsid.value;}net.onchange=selected;hiddenSsid.oninput=selected;let previousSsid='';async function request(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{return await fetch(url,{...options,signal:controller.signal});}finally{clearTimeout(timer);}}"
"async function search(){scan.disabled=true;scanStatus.textContent='正在扫描，请稍候…';try{const r=await request('/networks',{cache:'no-store'});if(!r.ok)throw Error();const rows=await r.json(),previous=net.value||previousSsid;net.replaceChildren(new Option('请选择 Wi-Fi',''));for(const row of rows){const o=new Option(row.ssid+(row.open?' · 开放':''),row.ssid);o.dataset.open=String(row.open);net.add(o);}if(previous&&!rows.some(row=>row.ssid===previous))net.add(new Option(previous+' · 上次使用',previous));if([...net.options].some(o=>o.value===previous))net.value=previous;net.disabled=false;scanStatus.textContent=rows.length?'请选择与电脑相同的网络':'未找到网络，请重新扫描，或手动填写隐藏网络。';}catch(e){scanStatus.textContent='扫描失败，请重试，或展开手动配置。';}finally{scan.disabled=false;selected();}}scan.onclick=search;async function init(){try{const r=await request('/setup-status',{cache:'no-store'});if(r.ok){const state=await r.json();previousSsid=state.ssid||'';if(state.error){s.textContent=state.error;s.setAttribute('role','alert');}}}catch(e){}await search();}init();"
"f.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f));if(hiddenSsid.value)data.ssid=hiddenSsid.value;if(!data.ssid){s.textContent='请选择或填写 Wi-Fi 名称';return;}if(Boolean(data.host)!==Boolean(data.pairingCode)){s.textContent='手动配置需要同时填写电脑 IP 和配对码';return;}save.disabled=true;try{const r=await request('/configure',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const message=await r.text();s.textContent=r.ok?'已保存，正在尝试连接 Wi-Fi；认证失败或 30 秒内未连上时，会自动恢复 Piko-Setup 热点。届时重新连接设备热点，打开 192.168.4.1 即可修改密码。连网成功后设备会自动寻找 Piko。请将手机或电脑切回原 Wi-Fi，在 Piko 的设置 → 系统与数据 → Piko Passport 中开启设备连接，并确认新设备。':message;if(!r.ok)selected();}catch(e){s.textContent='请求超时或连接中断，请检查设备屏幕。若 Wi-Fi 连接失败，30 秒后重新连接设备热点并打开此页面重试。';selected();}};</script></html>";
